// Ampliamento della libreria del laboratorio: almeno un composto noto per ogni elemento che ne forma
// (fino all'einsteinio, l'elemento più pesante ottenuto in quantità visibile), più idrocarburi, composti
// organici, biomolecole, farmaci, ioni e sali.
// Stessi criteri di molecules.js: nomi italiani (IUPAC o d'uso), SMILES in forma di Kekulé con cariche
// esplicite, stato a 25 °C e 1 atm (omesso quando è incerto). I composti dei metalli d e f sono scritti con
// il modello ionico, che è una semplificazione (il legame ha anche carattere covalente); quelli che sono
// davvero molecolari (TiCl₄, OsO₄, UF₆, HgCl₂…) con legami covalenti. Il banco non distingue
// stereoisomeri (cis/trans, enantiomeri D/L).

export const MORE_GROUPS = [
  { key: 'ossidi', label: 'Ossidi dei non metalli', after: 'inorganiche' },
  { key: 'alogenuri', label: 'Alogenuri e interalogeni', after: 'ossidi' },
  { key: 'idrocarburi', label: 'Idrocarburi', after: 'acidi' },
  { key: 'biomolecole', label: 'Biomolecole', after: 'organiche' },
  { key: 'farmaci', label: 'Farmaci, aromi e additivi', after: 'biomolecole' },
  { key: 'metalli', label: 'Composti dei metalli di transizione', after: 'ionici' },
  { key: 'lantanidi', label: 'Composti di lantanidi e attinidi', after: 'metalli' },
];

const SIMPLE_IONIC = 'Composto ionico (modello semplificato: nel solido reale il legame ha anche carattere covalente).';

/** Ossido o sale di un metallo scritto con il modello ionico. */
const ionic = (id, group, name, formula, smiles, extra = {}) => ({ id, group, name, formula, smiles, state: 'solido', desc: SIMPLE_IONIC, ...extra });

