function tm(id, name, formula, smiles, extra = {}) {
  return ionic(id, 'metalli', name, formula, smiles, { note: 'Il modello a ioni è una semplificazione: con i metalli di transizione il legame ha anche un carattere covalente.', ...extra });
}

function ln(id, name, formula, smiles, extra = {}) {
  return ionic(id, 'lantanidi', name, formula, smiles, { desc: 'Composto ionico formato dagli ioni del metallo e dagli ioni ossido O²⁻.', note: 'Il modello a ioni è una semplificazione utile per lantanidi e attinidi, i cui composti sono in gran parte ionici.', ...extra });
}
